/**
 * Definition for a binary tree node. public class TreeNode { int val; TreeNode left; TreeNode
 * right; TreeNode() {} TreeNode(int val) { this.val = val; } TreeNode(int val, TreeNode left,
 * TreeNode right) { this.val = val; this.left = left; this.right = right; } }
 */
class Solution {

  private int voyIndex = 0;

  private boolean recur(TreeNode node, int[] voyage, List<Integer> ans) {
    if (node == null) return true;
    if (voyage[voyIndex] != node.val) return false;
    voyIndex++;
    if (node.left != null && voyage[voyIndex] != node.left.val) {
      ans.add(node.val);
      return recur(node.right, voyage, ans) && recur(node.left, voyage, ans);
    }
    return recur(node.left, voyage, ans) && recur(node.right, voyage, ans);
  }

  public List<Integer> flipMatchVoyage(TreeNode root, int[] voyage) {
    List<Integer> ans = new LinkedList<>();
    if (recur(root, voyage, ans)) return ans;
    ans = new LinkedList<>();
    ans.add(-1);
    return ans;
  }
}

